<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';require_method('GET');$u=current_user();[$page,$per,$offset]=pagination();$where='l.tenant_id=?';$p=[$u['tenant_id']];if($u['role']==='MEMBER'){$where.=' AND c.created_by=?';$p[]=$u['id'];}if(!empty($_GET['status'])){$status=strtoupper((string)$_GET['status']);if(in_array($status,['SENT','FAILED','RETRY'],true)){$where.=' AND l.status=?';$p[]=$status;}}if(!empty($_GET['campaign_id'])){$where.=' AND c.public_id=?';$p[]=$_GET['campaign_id'];}$count=db()->prepare("SELECT COUNT(*) FROM email_logs l JOIN campaigns c ON c.id=l.campaign_id AND c.tenant_id=l.tenant_id WHERE {$where}");$count->execute($p);$total=(int)$count->fetchColumn();$s=db()->prepare("SELECT l.id,l.created_at time,c.name campaign,l.recipient_email recipient,a.sender_email account,l.status,COALESCE(l.error_message,l.provider_category) detail,l.retry_count retryCount FROM email_logs l JOIN campaigns c ON c.id=l.campaign_id AND c.tenant_id=l.tenant_id JOIN smtp_accounts a ON a.id=l.smtp_account_id AND a.tenant_id=l.tenant_id WHERE {$where} ORDER BY l.id DESC LIMIT ? OFFSET ?");$i=1;foreach($p as $v)$s->bindValue($i++,$v);$s->bindValue($i++,$per,PDO::PARAM_INT);$s->bindValue($i,$offset,PDO::PARAM_INT);$s->execute();respond($s->fetchAll(),200,['page'=>$page,'perPage'=>$per,'total'=>$total]);
